import 'dart:async';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:flutter_test/flutter_test.dart';import 'package:go_router/go_router.dart';import 'package:pet_profile_app/core/theme/app_theme.dart';import 'package:pet_profile_app/features/pet_care/context/presentation/away_planning_dashboard_tile_state.dart';import 'package:pet_profile_app/features/pet_care/context/presentation/providers/care_context_providers.dart';import 'package:pet_profile_app/features/pet_care/context/presentation/widgets/planned_absence_entry_tile.dart';import 'package:pet_profile_app/l10n/app_localizations.dart';
void main(){Widget b(Future<AwayPlanningDashboardTileState> f){return ProviderScope(overrides:[awayPlanningDashboardTileProvider.overrideWith((ref)=>f)],child:MaterialApp.router(theme:AppTheme.lightTheme,localizationsDelegates:AppLocalizations.localizationsDelegates,supportedLocales:AppLocalizations.supportedLocales,routerConfig:GoRouter(routes:[GoRoute(path:'/',builder:(_,__)=>const PlannedAbsenceEntryTile())])));} testWidgets('prompt',(t)async{await t.pumpWidget(b(Future.value(AwayPlanningDashboardTileState.prompt)));await t.pumpAndSettle();expect(find.byKey(const Key('planned_absence_entry_tile')),findsOneWidget);}); testWidgets('loading',(t)async{await t.pumpWidget(b(Completer<AwayPlanningDashboardTileState>().future));await t.pump();expect(find.byKey(const Key('planned_absence_entry_tile')),findsOneWidget);});}
